/* ---- Solution ---- */
.masthead {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.links {
  display: flex;
  gap: 16px;
}

@media (min-width: 600px) {
  .masthead {
    flex-direction: row;
    justify-content: space-between;
  }

  .links {
    gap: 24px;
  }
}
